insert into public.services (id, name, slug, summary, entity_examples) values
  ('f0000000-0000-4000-8000-000000000010', 'Keeping a blueprint true', 'keeping-a-blueprint-true', 'The service blueprint of this template itself — how a team finds Uno Blueprint, gets a service onto the board, uses it, and brings it back in line when the service moves. Replace it with your own service; until then it doubles as documentation.', '{"service":"Keeping a blueprint true — this template mapped as its own service, so the board doubles as the documentation.","phase":"Setup — the one-time work of getting a real service onto the board and signed off.","scenario":"Map your service — the run that turns a folder of documents, or someone else’s diagram, into a validated board.","path":"From your documents — the ingest route that reads a corpus of service documents with per-claim provenance.","step":"Import and verify — the column where a validated file in a repository becomes rows in the database.","lane":"Blueprint owner — the row for the person driving the map, read across every step."}'::jsonb);
insert into public.phases (id, service_id, name, summary, position) values
  ('f0000000-0000-4000-8000-000700010000', 'f0000000-0000-4000-8000-000000000010', 'Discover', 'The evaluation before any commitment: find the template, run it with no backend, and decide whether it fits the team.', 1),
  ('f0000000-0000-4000-8000-000700020000', 'f0000000-0000-4000-8000-000000000010', 'Setup', 'The one-time work of getting a real service onto the board and signed off — the onboarding use.', 2),
  ('f0000000-0000-4000-8000-000700030000', 'f0000000-0000-4000-8000-000000000010', 'Operate', 'The blueprint in daily use: check it against reality, trace a change through it, and cut the view an audience asked for.', 3),
  ('f0000000-0000-4000-8000-000700040000', 'f0000000-0000-4000-8000-000000000010', 'Maintain', 'Upkeep of the artifact itself — the service moved, so the map is brought back in line, and the team resumes using it. Loops back to Operate.', 4);
insert into public.scenarios (id, phase_id, name, summary, position, layout) values
  ('f0000000-0000-4000-8000-100000000001', 'f0000000-0000-4000-8000-000700010000', 'Find the template and see what it does', 'The evaluation before any commitment: the pitch, the bundled sample board, a run with nothing configured, and the decision that it fits.', 1, 'stacked'),
  ('f0000000-0000-4000-8000-200000000001', 'f0000000-0000-4000-8000-000700020000', 'Map your service', 'The ub:map pipeline from two starting points — a folder of documents, or somebody else’s diagram — converging on one validated, signed-off, imported blueprint.', 1, 'stacked'),
  ('f0000000-0000-4000-8000-300000000001', 'f0000000-0000-4000-8000-000700030000', 'Audit the check roster', 'ub:audit runs its roster of blind checks and lands what they find as triageable rows — and the re-run is where a finding that was closed too early comes back.', 1, 'stacked'),
  ('f0000000-0000-4000-8000-400000000001', 'f0000000-0000-4000-8000-000700030000', 'Ideate a change (what-if)', 'ub:whatif traces a proposed change through the dependency graph on a copy, and stops at a human gate — nothing lands that nobody agreed to.', 2, 'stacked'),
  ('f0000000-0000-4000-8000-500000000001', 'f0000000-0000-4000-8000-000700030000', 'Slice for an audience', 'ub:slice takes the one view an audience asked for out of the blueprint and carries it into presentation mode and PDF, still pointing at the cells it quotes.', 3, 'stacked'),
  ('f0000000-0000-4000-8000-600000000001', 'f0000000-0000-4000-8000-000700040000', 'Keep it current', 'The service moved and the board did not: resume the workspace, edit what changed, re-sign it, re-import. A blueprint is maintained, not delivered.', 1, 'stacked');
insert into public.paths (id, scenario_id, name, summary, note, kind) values
  ('f0000000-0000-4000-8000-110000000000', 'f0000000-0000-4000-8000-100000000001', 'A first look', 'Repository to running app to decision, with no account, no key, and no database anywhere.', null, 'happy'),
  ('f0000000-0000-4000-8000-210000000000', 'f0000000-0000-4000-8000-200000000001', 'From your documents', 'The ingest route: a corpus of service documents, read by subagents, with per-claim provenance on every cell.', null, 'happy'),
  ('f0000000-0000-4000-8000-220000000000', 'f0000000-0000-4000-8000-200000000001', 'From someone else’s diagram', 'The translate route: a FigJam, Miro or spreadsheet export mapped onto lane roles through a crosswalk, with the diagram’s gaps left visible.', null, 'variant'),
  ('f0000000-0000-4000-8000-310000000000', 'f0000000-0000-4000-8000-300000000001', 'Findings triaged', 'Every finding dismissed or genuinely resolved, and the re-run comes back quiet.', null, 'happy'),
  ('f0000000-0000-4000-8000-320000000000', 'f0000000-0000-4000-8000-300000000001', 'A critical finding reopens', 'A finding marked resolved before the fix landed: the next run re-detects the same fingerprint and reopens it.', null, 'variant'),
  ('f0000000-0000-4000-8000-410000000000', 'f0000000-0000-4000-8000-400000000001', 'Traced before it lands', 'Hypothetical to traced consequences to an accepted change request, with the base blueprint untouched throughout.', null, 'happy'),
  ('f0000000-0000-4000-8000-510000000000', 'f0000000-0000-4000-8000-500000000001', 'Stakeholder readout', 'From “show me my part” to a presented, exportable slice that still points at its cells.', null, 'happy'),
  ('f0000000-0000-4000-8000-610000000000', 'f0000000-0000-4000-8000-600000000001', 'Update what changed', 'The smallest loop in the template: one scenario edited, re-signed, and re-imported, with the rest reported as no-ops.', null, 'happy');
