insert into public.slices (id, service_id, kind, title, summary, actor, locale, authorship, position) values
  ('f0000000-0000-4000-8000-000500010000', 'f0000000-0000-4000-8000-000000000010', 'journey', 'The map, end to end', 'One pass down the blueprint owner’s own lane through Map your service, on the documents route — every moment where a person, rather than the pipeline, has to decide something.', 'Blueprint owner', 'en', 'generated', 1),
  ('f0000000-0000-4000-8000-000500020000', 'f0000000-0000-4000-8000-000000000010', 'step', 'The import moment, read top to bottom', 'One column of Map your service — “Import and verify” — read down every lane at once: the step where a file in a repo becomes rows in a database, and the step with the most that can go quietly wrong.', null, 'en', 'generated', 2),
  ('f0000000-0000-4000-8000-000500030000', 'f0000000-0000-4000-8000-000000000010', 'lane', 'Everything that happens out of sight', 'One lane of Audit the check roster — the subagent fleet, on the path where findings get triaged — read left to right: the half of the audit nobody watches, and the half that decides whether its verdicts can be trusted.', 'Subagent fleet', 'en', 'generated', 3);
insert into public.slides (id, slice_id, position, cell_ids, cell_keys, title, caption) values
  ('f0000000-0000-4000-8000-000600010001', 'f0000000-0000-4000-8000-000500010000', 1, array['f0000000-0000-4000-8000-210300020001'::uuid, 'f0000000-0000-4000-8000-210300020002'::uuid], array['keeping-a-blueprint-true/setup/map-your-service/from-your-documents/blueprint-owner/invoke-ub-map', 'keeping-a-blueprint-true/setup/map-your-service/from-your-documents/blueprint-owner/route-by-what-exists'], 'An ask, and the fork it creates', 'Mapping starts as a sentence, not a project. What happens next is decided by what already exists: a folder of documents routes to ingest, a diagram exported from somewhere else routes to translate. The two routes are the two paths of this scenario, and they rejoin four columns later.'),
  ('f0000000-0000-4000-8000-000600010002', 'f0000000-0000-4000-8000-000500010000', 2, array['f0000000-0000-4000-8000-210300020003'::uuid], array['keeping-a-blueprint-true/setup/map-your-service/from-your-documents/blueprint-owner/scope-and-settle-the-spine'], 'The two questions asked before anything is built', 'Scope and spine, in that order, and both answered by a person. Right-sizing decides whether this is one flow or the whole service; the spine decides whose journey the top lane follows. Everything drawn afterwards inherits both answers, which is why they are not left to the drafting.'),
  ('f0000000-0000-4000-8000-000600010003', 'f0000000-0000-4000-8000-000500010000', 3, array['f0000000-0000-4000-8000-210300020004'::uuid, 'f0000000-0000-4000-8000-210300020006'::uuid], array['keeping-a-blueprint-true/setup/map-your-service/from-your-documents/blueprint-owner/read-the-sources', 'keeping-a-blueprint-true/setup/map-your-service/from-your-documents/blueprint-owner/draft-the-structure'], 'What the owner still has to say out loud', 'On the documents route the corpus is not simply handed over: somebody names what is in scope and what is sensitive and excluded. The subagents that read it never make that call, and the cells that result carry provenance back to the documents that survived it.'),
  ('f0000000-0000-4000-8000-000600010004', 'f0000000-0000-4000-8000-000500010000', 4, array['f0000000-0000-4000-8000-210300020007'::uuid, 'f0000000-0000-4000-8000-210300020008'::uuid], array['keeping-a-blueprint-true/setup/map-your-service/from-your-documents/blueprint-owner/validate-and-review', 'keeping-a-blueprint-true/setup/map-your-service/from-your-documents/blueprint-owner/sign-off-per-scenario'], 'Two gates, one of them human', 'The validator is machinery and the reviewer is a fresh context, but accepting a finding is a judgement, and so is signing. The sign-off binds to a content hash rather than to a memory of having looked — a later edit shows the scenario as unsigned instead of quietly inheriting yesterday’s approval.'),
  ('f0000000-0000-4000-8000-000600010005', 'f0000000-0000-4000-8000-000500010000', 5, array['f0000000-0000-4000-8000-210300020010'::uuid], array['keeping-a-blueprint-true/setup/map-your-service/from-your-documents/blueprint-owner/deploy'], 'The end of the errand, not the end of the work', 'A URL is where mapping stops and maintaining starts. The Maintain phase loops back to this one on the overview canvas, because the next time the service moves, some part of this board is drawn again.'),
  ('f0000000-0000-4000-8000-000600020001', 'f0000000-0000-4000-8000-000500020000', 1, array['f0000000-0000-4000-8000-210300040009'::uuid], array['keeping-a-blueprint-true/setup/map-your-service/from-your-documents/claude-in-the-ide/import-and-verify'], 'What happens in the open', 'Claude writes the scenario through the service account and immediately reads it back, because a write that reports success and lands nothing is the failure mode this step exists to catch.'),
  ('f0000000-0000-4000-8000-000600020002', 'f0000000-0000-4000-8000-000500020000', 2, array['f0000000-0000-4000-8000-210300050009'::uuid], array['keeping-a-blueprint-true/setup/map-your-service/from-your-documents/pipeline-scripts/import-and-verify'], 'What runs underneath', 'One blueprint file becomes two targets in the same pass — a data module the keyless app imports, and a transactional seed for Postgres. Neither is asked to be trusted: the verification is a second, independent read, not the first write’s own report.'),
  ('f0000000-0000-4000-8000-000600020003', 'f0000000-0000-4000-8000-000500020000', 3, array['f0000000-0000-4000-8000-210300070009'::uuid], array['keeping-a-blueprint-true/setup/map-your-service/from-your-documents/references-guardrails/import-and-verify'], 'What the guardrail is doing while it happens', 'The interesting lane, and the reason to read this step vertically. A service-role key is in play for exactly this step, and a hook makes sure it never reaches disk or transcript. It runs on the owner’s own machine — the template ships the hook, it never holds the key.'),
  ('f0000000-0000-4000-8000-000600020004', 'f0000000-0000-4000-8000-000500020000', 4, array['f0000000-0000-4000-8000-210300030009'::uuid], array['keeping-a-blueprint-true/setup/map-your-service/from-your-documents/app-skill-surface/import-and-verify'], 'What you see at the end of it', 'The imported scenario, read back live in the browser. Until this renders, the import is a claim.'),
  ('f0000000-0000-4000-8000-000600030001', 'f0000000-0000-4000-8000-000500030000', 1, array['f0000000-0000-4000-8000-310300050003'::uuid], array['keeping-a-blueprint-true/operate/audit-the-check-roster/findings-triaged/subagent-fleet/dispatch-the-auditors'], 'One check each, and no peeking', 'The roster does not run as one long review. Each check goes out to its own fresh context holding exactly one check document and the shared export, which is what keeps a check’s judgement from being coloured by what another check already decided.'),
  ('f0000000-0000-4000-8000-000600030002', 'f0000000-0000-4000-8000-000500030000', 2, array['f0000000-0000-4000-8000-310300050004'::uuid], array['keeping-a-blueprint-true/operate/audit-the-check-roster/findings-triaged/subagent-fleet/collect-and-dedupe'], 'The shape is checked before the content is believed', 'An auditor that returns something malformed has failed its check — that is decided before any dedupe, so a broken run is reported as a failed check rather than absorbed as a quiet absence of findings.'),
  ('f0000000-0000-4000-8000-000600030003', 'f0000000-0000-4000-8000-000500030000', 3, array['f0000000-0000-4000-8000-310300050007'::uuid], array['keeping-a-blueprint-true/operate/audit-the-check-roster/findings-triaged/subagent-fleet/re-run-the-roster'], 'Why running it again is the normal state', 'A re-run is a full run. On this path the checks whose cells did not move come back with nothing, which is the point: the noise floor is low enough that a new finding means something changed.');
